svg.appendChild(el("text", {x: lastX - 4, y: lastY + 18, "text-anchor": "end", "font-size": 7.5, "font-weight": 700, fill: "#4a5568", "font-family": FF}, "2 ANS"));
if (Math.abs(policy - y2[n-1]) / y2[n-1] >= 0.03) {
