<div style="background:#f5f5f5;border-bottom:1px solid #d0d0d0;padding:10px 14px;display:flex;align-items:baseline;gap:16px;flex-wrap:wrap;">
<span style="font-size:13px;font-weight:700;color:#111;letter-spacing:0.02em;">BRUT BRENT&nbsp;: RÈGLEMENT QUOTIDIEN</span>
<span style="font-size:20px;font-weight:700;color:#111;">109,55&nbsp;$&nbsp;US</span>
<span style="font-size:13px;color:#3a7a55;">▲ +13,8&nbsp;% DEPUIS LE 21 SEPT.</span>
<span style="font-size:11px;color:#888;margin-left:auto;">QUOTIDIEN &nbsp;|&nbsp; 21 SEPT. AU 19 OCT. 2026</span>
</div>
<div style="padding:12px 14px 8px;">
<script>
(function(){
var _cs = document.currentScript;
var svg = document.createElementNS("http://www.w3.org/2000/svg","svg");
svg.setAttribute("viewBox","0 0 680 300");
svg.setAttribute("width","100%");
var FF = "-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif";
function el(tag, attrs, txt){ var e = document.createElementNS("http://www.w3.org/2000/svg", tag); for (var k in attrs) e.setAttribute(k, attrs[k]); if (txt !== undefined) e.textContent = txt; return e; }
var margin = {left:62, right:24, top:18, bottom:46};
var PW = 594, PH = 236;
var brent = [96.24,95.41,98.12,106.60,98.82,99.78,97.09,98.03,102.31,102.25,100.32,100.58,100.20,104.28,104.72,106.65,105.69,106.06,105.92,109.86,109.55];
var n = brent.length;
var lo = 90, hi = 115;
var ref = 100;
var priceIdx = 3, shipIdx = 16, waiverIdx = 19;
function xp(i){ return margin.left + (i/(n-1))*PW; }
function yp(v){ return margin.top + ((hi - v)/(hi - lo))*PH; }
function textW(s, fs, k){ return Math.ceil(s.length*fs*k); }
var t;
for (t = lo; t <= hi; t += 5) {
  svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: yp(t), y2: yp(t), stroke: "#ececec", "stroke-width": 0.5}));
}
svg.appendChild(el("rect", {x: xp(15), y: margin.top, width: xp(n-1) - xp(15), height: PH, fill: "#8a3030", "fill-opacity": 0.05}));
var refY = yp(ref);
svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: refY, y2: refY, stroke: "#6b7280", "stroke-width": 1, "stroke-dasharray": "3,3"}));
var d = "";
for (var i = 0; i < n; i++) { d += (i === 0 ? "M" : "L") + xp(i).toFixed(1) + " " + yp(brent[i]).toFixed(1) + " "; }
svg.appendChild(el("path", {d: d, fill: "none", stroke: "#4a5568", "stroke-width": 2.4, "stroke-linejoin": "round"}));
svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: margin.top + PH, y2: margin.top + PH, stroke: "#d8d8d8", "stroke-width": 1}));
var evs = [[shipIdx, "PRIDE FRAPPÉ"], [waiverIdx, "DÉROG. RUSSIE"]];
for (var k = 0; k < evs.length; k++) {
  var ex = xp(evs[k][0]);
  svg.appendChild(el("line", {x1: ex, x2: ex, y1: margin.top, y2: margin.top + PH, stroke: "#1a3560", "stroke-opacity": 0.5, "stroke-dasharray": "2,3", "stroke-width": 1}));
  var lw = textW(evs[k][1], 7, 0.68);
  var left = (ex - lw - 3) >= margin.left;
  svg.appendChild(el("text", {x: ex + (left ? -3 : 3), y: margin.top + 10, "text-anchor": left ? "end" : "start", "font-size": 7, "font-weight": 700, fill: "#1a3560", "font-family": FF}, evs[k][1]));
}
svg.appendChild(el("circle", {cx: xp(priceIdx), cy: yp(brent[priceIdx]), r: 3, fill: "#6b7280"}));
svg.appendChild(el("text", {x: xp(priceIdx) + 6, y: yp(brent[priceIdx]) + 3, "text-anchor": "start", "font-size": 7.5, "font-weight": 700, fill: "#6b7280", "font-family": FF}, "24 SEPT. : +8,6 % / JOUR"));
var lastX = xp(n-1);
var lastY = yp(brent[n-1]);
svg.appendChild(el("circle", {cx: lastX, cy: lastY, r: 3.5, fill: "#4a5568"}));
var pillText = brent[n-1].toFixed(2).replace(".", ",") + " $";
var pillW = textW(pillText, 9, 0.58) + 10;
var pillH = 16;
var pillX = lastX - pillW - 6;
if (pillX < margin.left) pillX = margin.left;
var pillY = lastY - pillH/2 + 14;
svg.appendChild(el("rect", {x: pillX, y: pillY, width: pillW, height: pillH, rx: 3, fill: "#e8a825"}));
svg.appendChild(el("text", {x: pillX + pillW/2, y: pillY + pillH/2 + 3, "text-anchor": "middle", "font-size": 9, "font-weight": 700, fill: "#111111", "font-family": FF}, pillText));
for (t = lo; t <= hi; t += 5) {
  svg.appendChild(el("text", {x: margin.left - 6, y: yp(t) + 3, "text-anchor": "end", "font-size": 8.5, fill: "#aaaaaa", "font-family": FF}, t + " $"));
}
var ticks = [[0, "21 SEPT."], [5, "28 SEPT."], [10, "5 OCT."], [15, "12 OCT."], [20, "19 OCT."]];
for (var j = 0; j < ticks.length; j++) {
  svg.appendChild(el("text", {x: xp(ticks[j][0]), y: margin.top + PH + 14, "text-anchor": "middle", "font-size": 8, fill: "#999999", "font-family": FF}, ticks[j][1]));
}
svg.appendChild(el("text", {x: lastX - 4, y: lastY - 10, "text-anchor": "end", "font-size": 7.5, "font-weight": 700, fill: "#4a5568", "font-family": FF}, "BRENT"));
if (Math.abs(ref - brent[n-1]) / brent[n-1] >= 0.03) {
  svg.appendChild(el("text", {x: margin.left + 10, y: refY - 10, "text-anchor": "start", "font-size": 7, "font-weight": 700, fill: "#6b7280", "font-family": FF}, "100 $"));
}
svg.appendChild(el("text", {x: xp(15) + 4, y: margin.top + PH - 6, "text-anchor": "start", "font-size": 7, "font-weight": 700, fill: "#8a3030", "font-family": FF}, "ATTAQUES NAVIRES ORMUZ"));
_cs.parentNode.appendChild(svg);
})();
</script>
</div>
<div style="font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;font-size:10px;color:#999;padding:4px 14px 10px;font-style:italic;">Source&nbsp;: Investing.com, règlements quotidiens des contrats à terme sur le Brent, du 21 septembre au 19 octobre 2026&nbsp;; Reuters&nbsp;; Commandement central des États-Unis. &nbsp;|&nbsp; hdq.ca</div>
</div>
</div>
<p style="font-size:11px;color:#666;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;margin-top:6px;">Prix de règlement quotidiens des contrats à terme sur le Brent du premier mois, en dollars américains le baril, 21 jours de bourse jusqu’au 19 octobre 2026. Les repères d’événements montrent la frappe du 13 octobre contre le GFS Pride et la levée, le 16 octobre, de certaines sanctions et de certains droits de douane visant les exportations d’énergie russe.</p>
<h2>Dérogation, élections de mi-mandat et éventail de scénarios</h2>
<p>Le président Trump a signé vendredi un décret levant certaines sanctions et certains droits de douane visant les exportations d’énergie russe, dans le but de faire baisser les prix de l’énergie avant les élections de mi-mandat du 3 novembre. Le Brent a reculé de jusqu’à 3&nbsp;$&nbsp;US durant les échanges de lundi, avec un sommet de 110,70&nbsp;$&nbsp;US et un creux de 106,82&nbsp;$&nbsp;US, avant de clôturer à peu près inchangé. Priyanka Sachdeva, de Phillip Nova, a dit que la dérogation «&nbsp;a fait peu pour régler les perturbations de l’approvisionnement à Ormuz&nbsp;», et Gelber and Associates a indiqué que l’incertitude sur ses modalités et sa durée limite la confiance que davantage de carburant russe atteindra le marché.</p>
<p>Bjarne Schieldrop, de SEB, a prévenu que toute hausse des volumes d’exportation par Ormuz pourrait être de courte durée, car l’Iran pourrait intensifier le conflit avant les élections de mi-mandat. Les prévisionnistes demeurent bien en deçà du prix actuel. Goldman Sachs, par la voix de Daan Struyven, retient un scénario central d’environ 80&nbsp;$&nbsp;US le baril de Brent au quatrième trimestre, avec des prix supérieurs à 120&nbsp;$&nbsp;US si les attaques contre Ormuz persistent et environ 125&nbsp;$&nbsp;US en décembre dans un scénario sévère. JPMorgan cite une juste valeur proche de 90&nbsp;$&nbsp;US.</p>
<p>La distinction compte. À 109,55&nbsp;$&nbsp;US, le marché escompte une perturbation bien au-delà des scénarios centraux des grands prévisionnistes, qui voient le niveau actuel comme un cas extrême appelé à se normaliser. Les dix prochains jours comportent quatre tests&nbsp;: le vote égyptien du 26 octobre, la décision de la Réserve fédérale les 27 et 28 octobre, la décision de la Banque du Canada le 28 octobre et les élections américaines du 3 novembre.</p>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Ce qu’ils ressentent</div>
<p>Les clients voient grimper l’essence et le diesel et entendent parler d’attaques contre des infrastructures saoudiennes et le transport maritime dans le Golfe. Ceux qui détiennent des actions énergétiques canadiennes se demandent s’ils doivent prendre des bénéfices ou en acheter davantage. D’autres craignent qu’un conflit commencé il y a des mois soit sans issue en vue, et veulent savoir si leur portefeuille est exposé.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Quoi dire</div>
<div class="script-box">Le pétrole se situe près de 110&nbsp;$&nbsp;US le baril parce que le transport par le détroit d’Ormuz a été réduit de plus de moitié et que des attaques ont atteint des infrastructures saoudiennes. La plupart des grands prévisionnistes s’attendent à un retour des prix vers 80 à 90&nbsp;$&nbsp;US, de sorte que 110&nbsp;$&nbsp;US reflète une prime de perturbation, pas une nouvelle normale. En même temps, le risque d’une nouvelle flambée est réel, et il se manifeste déjà dans l’essence et dans l’inflation canadienne. Je ne changerais pas votre plan à long terme à cause d’une semaine de manchettes. Ce que nous pouvons faire, c’est vérifier quelle part de votre portefeuille dépend du prix de l’énergie, dans un sens comme dans l’autre, et nous assurer que vos besoins de liquidités pour la prochaine année sont couverts.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Qui est touché</div>
<p><strong>Forte incidence&nbsp;:</strong> les clients ayant des positions concentrées dans l’énergie canadienne, et les clients dont l’entreprise a des coûts élevés de carburant ou de transport.</p>
<p><strong>Incidence variable&nbsp;:</strong> les retraités à revenu fixe qui font face à des coûts plus élevés d’essence et de chauffage mais détiennent des fonds d’actions larges qui incluent des producteurs d’énergie.</p>
<p><strong>Avantage potentiel&nbsp;:</strong> les investisseurs ayant une exposition diversifiée aux producteurs d’énergie canadiens, qui profitent de prix plus élevés, bien que le gain dépende de la durée.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Liste de vérification</div>
<div class="checklist-item">Mesurer la pondération de l’énergie dans les comptes des clients, y compris les fonds et les FNB.</div>
<div class="checklist-item">Repérer les clients dont un seul titre énergétique dépasse la limite de leur politique de placement.</div>
<div class="checklist-item">Confirmer que douze mois de besoins de liquidités sont couverts à l’extérieur des actions.</div>
<div class="checklist-item">Noter les dates&nbsp;: le 26 octobre, le 28 octobre et le 3 novembre.</div>
<div class="checklist-item">Préparer une courte note aux clients expliquant l’écart entre les prévisions et le prix actuel.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de suivi</div>
<div class="email-box" id="respond-email">
<strong>Objet&nbsp;:</strong> Pétrole près de 110&nbsp;$&nbsp;US&nbsp;: ce que cela signifie et ce que cela ne signifie pas<br><br>
Bonjour [Nom du client],<br><br>
Merci de l’appel. En résumé&nbsp;: le Brent se situe près de 110&nbsp;$&nbsp;US parce que les flux maritimes dans le Golfe ont fortement diminué et que des infrastructures saoudiennes sont attaquées. Les grands prévisionnistes voient les prix revenir vers 80 à 90&nbsp;$&nbsp;US si le transport se normalise, de sorte que le niveau actuel reflète une prime de perturbation.<br><br>
J’examinerai votre exposition à l’énergie et vos réserves de liquidités et je vous enverrai un court résumé cette semaine.<br><br>
[Votre nom]<br><br>
<em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''respond-email'', this)">Copier le courriel</button>
</div>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Profils de clients à cibler</div>
<p><strong>Investisseurs ayant des placements énergétiques concentrés&nbsp;:</strong> un titre ou un secteur qui a monté avec le pétrole comporte un risque différent si les prix se normalisent.</p>
<p><strong>Propriétaires d’entreprise aux coûts de carburant élevés&nbsp;:</strong> le camionnage, l’agriculture et la construction font face à des coûts d’intrants plus élevés et ont peu de moyens de s’en couvrir.</p>
<p><strong>Investisseurs autonomes réagissant aux manchettes&nbsp;:</strong> les fortes variations quotidiennes du pétrole compliquent la distinction entre signal et bruit.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Phrase d’accroche</div>
<div class="script-box">Le pétrole se situe près de 110&nbsp;$&nbsp;US alors que la plupart des prévisionnistes s’attendent à 80 à 90&nbsp;$&nbsp;US, et les dix prochains jours comprennent des décisions en Égypte, aux États-Unis et au Canada. J’appelle donc quelques personnes pour parler de la façon de rester bien positionné sans réagir aux manchettes.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Proposition de valeur</div>
<p>Un investisseur autonome voit le prix du pétrole, mais pas l’écart entre celui-ci et les scénarios centraux qu’utilisent les institutions. Un examen de l’exposition à l’énergie et des besoins de liquidités transforme une manchette en plan assorti de dates précises.</p>
<p>Le conseiller propose une analyse précise&nbsp;: quelle part du portefeuille évolue avec le pétrole, ce qui se passe si les prix reviennent à 90&nbsp;$&nbsp;US, et ce qui se passe s’ils dépassent 120&nbsp;$&nbsp;US.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Questions de découverte</div>
<div class="checklist-item">Quelle part de votre portefeuille se trouve dans des actions ou des fonds énergétiques&nbsp;?</div>
<div class="checklist-item">Avez-vous changé quoi que ce soit depuis que le pétrole a commencé à monter&nbsp;?</div>
<div class="checklist-item">Dans quelle mesure des coûts de carburant plus élevés toucheraient-ils votre ménage ou votre entreprise&nbsp;?</div>
<div class="checklist-item">Combien de mois de dépenses détenez-vous à l’extérieur des actions&nbsp;?</div>
<div class="checklist-item">Qui surveille vos positions quand les marchés bougent rapidement&nbsp;?</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de prospection</div>
<div class="email-box" id="prospect-email">
<strong>Objet&nbsp;:</strong> Pétrole près de 110&nbsp;$&nbsp;US&nbsp;: dans quelle mesure votre portefeuille est-il exposé&nbsp;?<br><br>
Bonjour [Nom du prospect],<br><br>
Le Brent a atteint 110&nbsp;$&nbsp;US alors que le transport par le détroit d’Ormuz a diminué de plus de moitié, tandis que de nombreux prévisionnistes s’attendent à un recul des prix. Je vous transmets un court résumé de la façon dont l’exposition à l’énergie se manifeste dans un portefeuille canadien et de ce qu’il faut examiner avant la fin du mois.<br><br>
Un appel de quinze minutes cette semaine vous serait-il utile&nbsp;?<br><br>
[Votre nom]<br><br>
<em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''prospect-email'', this)">Copier le courriel</button>
</div>',
  '[{"value":"109,55 $ US","label":"Règlement du Brent, 19 octobre"},{"value":"8,5 M","label":"Flux brut du Golfe, b/j"},{"value":"27,8 %","label":"IPC essence, sur un an"},{"value":"3 nov.","label":"Élections américaines de mi-mandat"}]',
